type Bin = {capacity: number; quantity: number};
export function allocate(amount: number, bins: Bin[]): number {
  let remaining = amount;
  for (const bin of bins) {
    const moved = Math.min(remaining, bin.capacity - bin.quantity);
    bin.quantity += moved; remaining -= moved;
  }
  return remaining;
}

