  const pane = useRef(null);
  useEffect(() => { load().then(setMessages); }, [load]);
  useEffect(() => {
    pane.current.scrollTop = pane.current.scrollHeight;
  }, [messages]);
  return <div ref={pane}><VirtualList items={messages} estimateSize={() => 30} /></div>;
}

let generation = 0;
export async function openSettings(dialog, fetchForm) {
  const current = ++generation;
  const form = await fetchForm();
  if (current !== generation) return;
  dialog.replaceChildren(form);
  dialog.showModal();
  dialog.querySelector("input")?.focus();
}
export function closeSettings(dialog) {
  ++generation;
  dialog.close();
}

