export async function createOrder(req, db, mailer) {
  const items = JSON.parse(req.body.items);
  if (!Array.isArray(items) || items.length === 0) throw new Error("items required");
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const order = await db.insert("orders", {items, total});
  try { await mailer.send(order); } catch (error) { console.error(error); }
  return order;
}

