import time
import requests
def collect(url):
    for delay in (1, 2, 4):
        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            return response.json()
        except requests.RequestException:
            time.sleep(delay)
    raise RuntimeError("feed unavailable")
